#include <iostream>
#include <vector>
#include <string>
#include <stack>
#include <utility>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<vector<bool>> vis(n, vector<bool>(m, false));
    string hh, vv;
    cin >> hh >> vv;

    stack<pair<int, int>> st;
    st.push({0, 0});
    vis[0][0] = true;
    int reached = 1;

    while (!st.empty()) {
        auto [x, y] = st.top();
        st.pop();

        int ny = y + (hh[x] == '>' ? 1 : -1);
        if (ny >= 0 && ny < m && !vis[x][ny]) {
            vis[x][ny] = true;
            st.push({x, ny});
            ++reached;
        }

        int nx = x + (vv[y] == 'v' ? 1 : -1);
        if (nx >= 0 && nx < n && !vis[nx][y]) {
            vis[nx][y] = true;
            st.push({nx, y});
            ++reached;
        }
    }

    cout << (reached == n * m ? "YES" : "NO");
    return 0;
}

