using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<vector<bool>> vis(n, vector<bool>(m, false));
    string hh, vv;
    cin >> hh >> vv;

    stack<pair<int, int>> st;
    st.push({0, 0});
    vis[0][0] = true;
    int r = 1;

    while (!st.empty()) {
        auto c = st.top();
        st.pop();

        int x = c.first;
        int y = c.second;

        if (hh[x] == '>' && y + 1 < m && !vis[x][y + 1]) {
            vis[x][y + 1] = true;
            st.push({x, y + 1});
            ++r;
        } else if (hh[x] == '<' && y - 1 >= 0 && !vis[x][y - 1]) {
            vis[x][y - 1] = true;
            st.push({x, y - 1});
            ++r;
        }

        if (vv[y] == 'v' && x + 1 < n && !vis[x + 1][y]) {
            vis[x + 1][y] = true;
            st.push({x + 1, y});
            ++r;
        } else if (vv[y] == '^' && x - 1 >= 0 && !vis[x - 1][y]) {
            vis[x - 1][y] = true;
            st.push({x - 1, y});
            ++r;
        }
    }

    cout << (r == n * m ? "YES" : "NO");
    return 0;
}

